import { expect, expectStatus, test, type Document, type Extraction } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("a certificate that expires today can still be approved", { tag: "@LIF-07" }, async ({ apiAs, factory }) => {
    // Arrange
    // The server decides "today" from its UTC clock (app.state.today = utcnow().date()), so the
    // expiry is built from the same UTC date. Only expiry before today is refused.
    const today = new Date().toISOString().slice(0, 10);
    const member = await apiAs("member");
    const vendor = await factory.vendor({ as: "member" });
    await factory.upload(vendor.id, "w9");
    await factory.upload(vendor.id, "contract");
    const certificate = [
      "Insurer: Harbor Mutual",
      "Policy Number: HM-55-1290",
      "Coverage Amount: $2,000,000",
      `Expiry Date: ${today}`,
      "",
    ].join("\n");
    const insurance = await expectStatus<Document>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: { name: "insurance_certificate_expires_today.txt", mimeType: "text/plain", buffer: Buffer.from(certificate) },
        },
      }),
      201,
    );
    await expect
      .poll(
        async () => {
          const documents = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
          return documents.map((d) => d.status).sort();
        },
        { message: "extraction finishes for all three documents", timeout: 30_000 },
      )
      .toEqual(["extracted", "extracted", "extracted"]);
    await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
    const pending = await factory.extraction(insurance.id, "member");
    expect(pending.status, "insurance extraction awaits review").toBe("pending_review");

    // Act
    const reviewer = await apiAs("reviewer");
    const response = await reviewer.post(`/api/extractions/${pending.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const decided = await expectStatus<Extraction>(response, 200);
    expect(decided.status).toBe("approved");
    const stored = await factory.extraction(insurance.id, "reviewer");
    expect(stored.status, "approval is stored, not just echoed").toBe("approved");
  });
});
